Chessground(window.document.getElementById('board-4'), { orientation: 'black', coordinatesOnSquares: true, ranksPosition: 'left' });
Chessground(window.document.getElementById('board-5'), { orientation: 'white', coordinatesOnSquares: true });

// verify: board is rendered, shape is drawn
const boards = ['board-1','board-2','board-3','board-4','board-5'].map(id => window.document.getElementById(id));
for (const b of boards) {
  const board = b.querySelector('cg-board');
  const squares = b.querySelectorAll('square').length;
  const pieces = b.querySelectorAll('piece').length;
  const shapes = b.querySelectorAll('.cg-shapes *').length; // rough
  console.log(b.id, { squares, pieces });
}
```

