// One-off smoke check: loads demo.html in jsdom and executes the same module
// script the page runs, against the tsc-compiled dist/ output.
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

const html = readFileSync(new URL('./demo.html', import.meta.url), 'utf8');
const dom = new JSDOM(html, { url: 'http://localhost/demo.html', pretendToBeVisual: true });
const { window } = dom;

// expose the DOM to the ESM modules imported below
for (const k of [
  'window',
  'document',
  'navigator',
  'requestAnimationFrame',
  'cancelAnimationFrame',
  'HTMLElement',
  'Element',
  'Node',
  'SVGElement',
  'getComputedStyle',
  'Event',
  'CustomEvent',
  'MouseEvent',
  'DOMRect',
])
  Object.defineProperty(globalThis, k, { value: window[k], configurable: true, writable: true });
const pageErrors = [];
window.addEventListener('error', e => pageErrors.push(e.message));

const { Chessground } = await import('./dist/chessground.js');

// the exact script from demo.html <script type="module">
Chessground(window.document.getElementById('board-1'), {});
Chessground(window.document.getElementById('board-2'), {
  fen: 'r2q2k1/1p6/p2p4/2pN1rp1/N1Pb2Q1/8/PP1B4/R6K b - - 2 25',
});
Chessground(window.document.getElementById('board-3'), {
  drawable: {
    autoShapes: [
      { orig: 'a2', dest: 'a6', brush: 'green', label: { text: 'A' }, modifiers: { hilite: '#fff' } },
      { orig: 'b2', dest: 'b6', brush: 'blue', label: { text: 'B' }, modifiers: { lineWidth: 6 } },
      { orig: 'c2', dest: 'c4', brush: 'red', label: { text: 'C' } },
      { orig: 'd2', dest: 'd3', brush: 'green', label: { text: 'D' } },
      { orig: 'f1', dest: 'h3', brush: 'blue', label: { text: 'F' } },
      { orig: 'g1', dest: 'f3', brush: 'yellow', label: { text: 'E' } },
    ],
  },
});
Chessground(window.document.getElementById('board-4'), {
  orientation: 'black',
  coordinatesOnSquares: true,
  ranksPosition: 'left',
});
Chessground(window.document.getElementById('board-5'), {
  orientation: 'white',
  coordinatesOnSquares: true,
});

let failures = 0;
const check = (label: string, ok: boolean, detail: unknown = undefined): void => {
  console.log(ok ? 'OK  ' : 'FAIL', label, detail === undefined ? '' : JSON.stringify(detail));
  if (!ok) failures++;
};

// pieces include the ghost piece element; board-2's fen has 19 pieces
const expectedPieces: Record<string, number> = {
  'board-1': 33, // 32 + ghost
  'board-2': 20, // 19 (fen) + ghost
  'board-3': 33,
  'board-4': 33,
  'board-5': 33,
};
for (const [id, expected] of Object.entries(expectedPieces)) {
  const el = window.document.getElementById(id)!;
  const pieces = el.querySelectorAll('piece').length;
  check(`${id} cg-board + ${expected} piece elements`, !!el.querySelector('cg-board') && pieces === expected, {
    pieces,
  });
}

// board-4: black orientation applied to the wrap element
check(
  'board-4 orientation-black class',
  window.document.getElementById('board-4')!.classList.contains('orientation-black'),
);

// board-3: the 6 autoShapes rendered into the shapes svg (shapes + labels)
const shapes = window.document.querySelectorAll(
  '#board-3 svg.cg-shapes shape, #board-3 svg.cg-shapes path, #board-3 svg.cg-shapes line, #board-3 svg.cg-shapes ellipse',
).length;
check('board-3 svg shape nodes', shapes >= 6, { shapes });

if (pageErrors.length) {
  failures++;
  console.log('FAIL page errors:', pageErrors);
}
if (failures) {
  console.log(`\ndemo smoke: FAILED (${failures} problems)`);
  process.exit(1);
}
console.log('\ndemo smoke: all boards loaded and rendered');

